package models

type AgentRequest struct {
	Message string `json:"message" binding:"required"`
}

type AgentResponse struct {
	Response string `json:"response"`
}

type AgentConfig struct {
	Name        string  `json:"name"`
	Provider    string  `json:"provider"`
	Model       string  `json:"model"`
	Temperature float64 `json:"temperature"`
	MaxTokens   int     `json:"max_tokens"`
	MemorySize  int     `json:"memory_size"`
}

// ProjectIdea represents a project idea generated by the AI
type ProjectIdea struct {
	Title                 string   `json:"title"`
	Description           string   `json:"description"`
	Difficulty            string   `json:"difficulty"` // "Beginner", "Intermediate", or "Advanced"
	EstimatedTime         string   `json:"estimatedTime"`
	EstimatedHoursPerWeek string   `json:"estimatedHoursPerWeek"`
	KeyTechnologies       []string `json:"keyTechnologies"`
	KeyFeatures           []string `json:"keyFeatures"`
	LearningOutcomes      []string `json:"learningOutcomes"`
}

// ProjectIdeaResponse represents the response structure for project ideas
type ProjectIdeaResponse struct {
	ProjectIdeas []ProjectIdea `json:"projectIdeas"`
}

// RoadmapResource represents an educational resource for a roadmap step
type RoadmapResource struct {
	Title string `json:"title"`
	URL   string `json:"url"`
	Type  string `json:"type"` // "Article", "Video", "Course", or "Documentation"
}

// BasicRoadmapStep represents a step in the project roadmap without resources
type BasicRoadmapStep struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// RoadmapStep represents a step in the project roadmap with resources
type RoadmapStep struct {
	Title        string            `json:"title"`
	Description  string            `json:"description"`
	TimeEstimate string            `json:"timeEstimate"`
	Resources    []RoadmapResource `json:"resources"`
}

// BasicRoadmap represents a project roadmap with steps but without resources
type BasicRoadmap struct {
	Steps []BasicRoadmapStep `json:"steps"`
}

// Roadmap represents a project roadmap with steps including resources
type Roadmap struct {
	Steps []RoadmapStep `json:"steps"`
}

// BasicRoadmapResponse represents the response structure for roadmap generation without resources
type BasicRoadmapResponse struct {
	Roadmap BasicRoadmap `json:"roadmap"`
}

// RoadmapResponse represents the response structure for roadmap generation including resources
type RoadmapResponse struct {
	Roadmap Roadmap `json:"roadmap"`
}

// StepResources represents resources for a specific roadmap step
type StepResources struct {
	StepTitle string            `json:"stepTitle"`
	Resources []RoadmapResource `json:"resources"`
}

// RoadmapResourcesResponse represents the response structure for roadmap resources
type RoadmapResourcesResponse struct {
	StepResources []StepResources `json:"stepResources"`
}

// ProjectChecklist represents a checklist for project completion
type ProjectChecklist struct {
	Items []ChecklistItem `json:"items"`
}

// ChecklistItem represents a single item in a project checklist
type ChecklistItem struct {
	Description string `json:"description"`
	Category    string `json:"category"` // e.g., "Requirements", "Setup", "Testing", etc.
	Priority    string `json:"priority"` // "High", "Medium", "Low"
}

// CurriculumAlignment represents how a project aligns with curriculum topics
type CurriculumAlignment struct {
	Topics     []string          `json:"topics"`     // Main curriculum topics covered
	Categories []TopicCategory   `json:"categories"` // Broader categories the project fits into
	Skills     []CurriculumSkill `json:"skills"`     // Specific skills developed through the project
}

// CurriculumSkill represents a skill developed through the project
type CurriculumSkill struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Level       string `json:"level"` // "Beginner", "Intermediate", "Advanced"
}

// TopicCategory represents a category of curriculum topics
type TopicCategory struct {
	Name          string   `json:"name"`
	Subcategories []string `json:"subcategories"`
}

// ProjectRoadmapWithChecklist represents a roadmap with a checklist and curriculum alignment
type ProjectRoadmapWithChecklist struct {
	Roadmap             Roadmap             `json:"roadmap"`
	Checklist           ProjectChecklist    `json:"checklist"`
	CurriculumAlignment CurriculumAlignment `json:"curriculumAlignment"`
}

// ProjectRoadmapWithChecklistResponse represents the response structure for roadmap generation with checklist
type ProjectRoadmapWithChecklistResponse struct {
	Response ProjectRoadmapWithChecklist `json:"response"`
}
